function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const yes = function (x) { return s(x).toLowerCase() === 'yes'; };
function cols(node, names, label) { const h = (($(node).first().json.values || [[]])[0] || []).map(s); const C = {}; for (const n of names) { const i = h.indexOf(n); if (i < 0) { throw new Error('ABORT: ' + label + ' column missing ' + n); } C[n] = colLetter(i); } return C; }
const IC = cols('GET INV header', ['investor', 'contact_person', 'email', 'sector'], 'INVESTORS');
const PC = cols('GET PIPE header', ['investor', 'email', 'notes'], 'PIPELINE');
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (inv.length < 200) { throw new Error('ABORT: INVESTORS only ' + inv.length); }
if (pipe.length < 5200) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
const base = inv.filter(function (r) { return nz(r.investor) === 'elevationcapital'; });
if (base.length !== 1) { throw new Error('ABORT: Elevation Capital resolves to ' + base.length + ' rows'); }
const b = base[0];
const STAGE = s(b.stage), CHQ = s(b.cheque_inr_cr);
// each partner sees a different sector (Thesis tab); keep the firm's stage and cheque
const KEEP = { investor: 'Elevation Capital - Healthcare (Shourya)', contact_person: 'Shourya', email: 'shourya@elevationcapital.com', sector: 'Healthcare, HealthTech, Biotech, Pharma, MedTech' };
const ADD = [
  { investor: 'Elevation Capital - Consumer & Mobility (Pranay)', contact_person: 'Pranay', email: 'pranay@elevationcapital.com', cc: '', sector: 'Consumer brands, EV, Logistics', stage: STAGE, cheque_inr_cr: CHQ },
  { investor: 'Elevation Capital - Consumer Tech & EdTech (Shreedhar)', contact_person: 'Shreedhar', email: 'shreedhar@elevationcapital.com', cc: '', sector: 'Consumer tech, EdTech, TravelTech', stage: STAGE, cheque_inr_cr: CHQ },
  { investor: 'Elevation Capital - FinTech (Lalit)', contact_person: 'Lalit', email: 'lalit@elevationcapital.com', cc: '', sector: 'FinTech', stage: STAGE, cheque_inr_cr: CHQ },
  { investor: 'Elevation Capital - DeepTech (Akshat)', contact_person: 'Akshat', email: 'akshat@elevationcapital.com', cc: '', sector: 'DeepTech, Sustainability, Defence, Semiconductors', stage: STAGE, cheque_inr_cr: CHQ }
];
const have = {}; for (const r of inv) { have[nz(r.investor)] = 1; }
const appends = ADD.filter(function (a) { return !have[nz(a.investor)]; });
const idata = [];
for (const f of Object.keys(KEEP)) { if (s(b[f]) === KEEP[f]) { continue; } idata.push({ range: 'INVESTORS!' + IC[f] + b.row_number, values: [[KEEP[f]]] }); }
// queued deals move to the partner whose sector fits the startup; sent rows keep their history
const MOVE = { healthymaster: ADD[0], sahaj: ADD[1] };
const pdata = [], moved = [], leftAlone = [];
for (const p of pipe) { if (nz(p.investor) !== 'elevationcapital') { continue; }
  if (yes(p.deal_shared)) { continue; }
  const t = MOVE[nz(p.startup)];
  if (!t) { leftAlone.push([p.row_number, s(p.deal_id), s(p.startup)]); continue; }
  const n = s(p.notes);
  pdata.push({ range: 'PIPELINE!' + PC.investor + p.row_number, values: [[t.investor]] }, { range: 'PIPELINE!' + PC.email + p.row_number, values: [[t.email]] },
    { range: 'PIPELINE!' + PC.notes + p.row_number, values: [[(n ? n + ' | ' : '') + 'MOVED 2026-09-12 - Elevation split by partner sector']] });
  moved.push([p.row_number, s(p.deal_id), s(p.startup), t.investor]); }
if (appends.length > 4) { throw new Error('ABORT: too many appends'); }
const data = idata.concat(pdata);
if (!data.length) { data.push({ range: 'INVESTORS!' + IC.investor + '1', values: [['investor']] }); }
return [{ json: { base_row: b.row_number, was: s(b.investor), stage: STAGE, cheque: CHQ, appends: appends, moved: moved, queued_left_alone: leftAlone, data: data } }];

const a = $('Plan').first().json.appends || [];
if (!a.length) { return [{ json: { __none: true } }]; }
return a.map(function (r) { return { json: r }; });

function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const plan = $('Plan').first().json;
const inv = $input.all().map(function (i) { return i.json; });
const rows = inv.filter(function (r) { return nz(r.investor).indexOf('elevationcapital') === 0; }).map(function (r) { return [r.row_number, s(r.investor), s(r.contact_person), s(r.email), s(r.sector), s(r.stage), s(r.cheque_inr_cr)]; });
const plain = inv.filter(function (r) { return nz(r.investor) === 'elevationcapital'; }).length;
return [{ json: { elevation_rows: rows, still_one_combined_row: plain, moved: plan.moved, queued_left_alone: plan.queued_left_alone, ok: rows.length === 5 && plain === 0 } }];
